PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
PRAGMA synchronous=NORMAL;
PRAGMA temp_store=MEMORY;
PRAGMA cache_size=-8000;
PRAGMA mmap_size=67108864;

CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS data_sources(source_id TEXT PRIMARY KEY,name TEXT NOT NULL,domain TEXT NOT NULL,homepage TEXT NOT NULL,download_url TEXT,api_url TEXT,license_id TEXT,license_url TEXT,redistribution TEXT NOT NULL DEFAULT 'review_required' CHECK(redistribution IN ('allowed','restricted','metadata_only','review_required','prohibited')),attribution TEXT,update_policy TEXT NOT NULL DEFAULT 'manual',enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN(0,1)),notes TEXT);
CREATE TABLE IF NOT EXISTS dataset_releases(release_id INTEGER PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources(source_id),upstream_version TEXT,retrieved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,source_url TEXT NOT NULL,license_snapshot TEXT,checksum_sha256 TEXT,byte_size INTEGER,local_path TEXT,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','downloading','verified','indexed','failed','blocked_license')),record_count INTEGER,error TEXT);
CREATE TABLE IF NOT EXISTS entities(entity_id INTEGER PRIMARY KEY,entity_type TEXT NOT NULL CHECK(entity_type IN('gene','transcript','protein','protein_structure','variant','organism','compound','reaction','pathway','cell','tissue','disease','assay','publication','dataset','image','other')),canonical_name TEXT,description TEXT,taxon_id INTEGER,properties_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_entities_type_name ON entities(entity_type,canonical_name);
CREATE TABLE IF NOT EXISTS identifiers(namespace TEXT NOT NULL,identifier TEXT NOT NULL,entity_id INTEGER NOT NULL REFERENCES entities(entity_id) ON DELETE CASCADE,is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN(0,1)),source_id TEXT REFERENCES data_sources(source_id),PRIMARY KEY(namespace,identifier)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS idx_identifiers_entity ON identifiers(entity_id);
CREATE TABLE IF NOT EXISTS source_records(record_id INTEGER PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources(source_id),release_id INTEGER REFERENCES dataset_releases(release_id),source_record_key TEXT NOT NULL,entity_id INTEGER REFERENCES entities(entity_id),record_type TEXT NOT NULL,raw_json TEXT NOT NULL,raw_sha256 TEXT NOT NULL,retrieved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(source_id,source_record_key,raw_sha256));
CREATE INDEX IF NOT EXISTS idx_source_records_entity ON source_records(entity_id);
CREATE TABLE IF NOT EXISTS sequences(entity_id INTEGER PRIMARY KEY REFERENCES entities(entity_id) ON DELETE CASCADE,molecule_type TEXT NOT NULL CHECK(molecule_type IN('protein','dna','rna','other')),sequence TEXT NOT NULL,sequence_sha256 TEXT NOT NULL,length INTEGER NOT NULL CHECK(length>=0),alphabet TEXT,source_record_id INTEGER REFERENCES source_records(record_id),UNIQUE(sequence_sha256,molecule_type));
CREATE INDEX IF NOT EXISTS idx_sequences_hash ON sequences(sequence_sha256);
CREATE TABLE IF NOT EXISTS structures(entity_id INTEGER PRIMARY KEY REFERENCES entities(entity_id) ON DELETE CASCADE,format TEXT NOT NULL,method TEXT,resolution_angstrom REAL,chain_count INTEGER,residue_count INTEGER,local_path TEXT,remote_url TEXT,checksum_sha256 TEXT,source_record_id INTEGER REFERENCES source_records(record_id));
CREATE TABLE IF NOT EXISTS compounds(entity_id INTEGER PRIMARY KEY REFERENCES entities(entity_id) ON DELETE CASCADE,canonical_smiles TEXT,isomeric_smiles TEXT,inchi TEXT,inchikey TEXT,formula TEXT,molecular_weight REAL,charge INTEGER,source_record_id INTEGER REFERENCES source_records(record_id));
CREATE INDEX IF NOT EXISTS idx_compounds_inchikey ON compounds(inchikey);
CREATE TABLE IF NOT EXISTS reactions(entity_id INTEGER PRIMARY KEY REFERENCES entities(entity_id) ON DELETE CASCADE,reaction_smiles TEXT,rhea_id TEXT,ec_number TEXT,source_record_id INTEGER REFERENCES source_records(record_id));
CREATE TABLE IF NOT EXISTS measurements(measurement_id INTEGER PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources(source_id),source_record_id INTEGER REFERENCES source_records(record_id),enzyme_entity_id INTEGER REFERENCES entities(entity_id),substrate_entity_id INTEGER REFERENCES entities(entity_id),reaction_entity_id INTEGER REFERENCES entities(entity_id),parameter TEXT NOT NULL,value_original REAL NOT NULL,unit_original TEXT NOT NULL,value_si REAL,unit_si TEXT,qualifier TEXT NOT NULL DEFAULT 'exact',temperature_kelvin REAL,ph REAL,organism_entity_id INTEGER REFERENCES entities(entity_id),reference_doi TEXT,assay_context_json TEXT NOT NULL DEFAULT '{}',curation_status TEXT NOT NULL DEFAULT 'unreviewed');
CREATE INDEX IF NOT EXISTS idx_measurements_parameter ON measurements(parameter);
CREATE INDEX IF NOT EXISTS idx_measurements_enzyme ON measurements(enzyme_entity_id);
CREATE INDEX IF NOT EXISTS idx_measurements_substrate ON measurements(substrate_entity_id);
CREATE TABLE IF NOT EXISTS relationships(relationship_id INTEGER PRIMARY KEY,subject_entity_id INTEGER NOT NULL REFERENCES entities(entity_id) ON DELETE CASCADE,predicate TEXT NOT NULL,object_entity_id INTEGER NOT NULL REFERENCES entities(entity_id) ON DELETE CASCADE,source_record_id INTEGER REFERENCES source_records(record_id),confidence REAL CHECK(confidence IS NULL OR(confidence>=0 AND confidence<=1)),properties_json TEXT NOT NULL DEFAULT '{}',UNIQUE(subject_entity_id,predicate,object_entity_id,source_record_id));
CREATE INDEX IF NOT EXISTS idx_relationships_subject ON relationships(subject_entity_id,predicate);
CREATE INDEX IF NOT EXISTS idx_relationships_object ON relationships(object_entity_id,predicate);
CREATE TABLE IF NOT EXISTS artifacts(artifact_id INTEGER PRIMARY KEY,entity_id INTEGER REFERENCES entities(entity_id),artifact_type TEXT NOT NULL,format TEXT NOT NULL,local_path TEXT NOT NULL,checksum_sha256 TEXT NOT NULL,byte_size INTEGER NOT NULL,compression TEXT,license_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(checksum_sha256,local_path));
CREATE TABLE IF NOT EXISTS sync_jobs(job_id INTEGER PRIMARY KEY,source_id TEXT NOT NULL REFERENCES data_sources(source_id),release_id INTEGER REFERENCES dataset_releases(release_id),state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN('queued','running','paused','completed','failed','cancelled')),cursor TEXT,bytes_downloaded INTEGER NOT NULL DEFAULT 0,records_processed INTEGER NOT NULL DEFAULT 0,last_error TEXT,started_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE VIRTUAL TABLE IF NOT EXISTS entity_fts USING fts5(canonical_name,description,entity_type UNINDEXED,tokenize='unicode61 remove_diacritics 2');
CREATE VIRTUAL TABLE IF NOT EXISTS record_fts USING fts5(title,abstract,body,source_id UNINDEXED,tokenize='unicode61 remove_diacritics 2');
INSERT OR IGNORE INTO schema_migrations(version,description) VALUES(1,'Initial unified mobile-first scientific schema');
